import{ax as i,A as a,aQ as t,z as e}from"./chunks/framework.BWRXlwpK.js";const h=JSON.parse('{"title":"Agent","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"ai/ai-agent.md","filePath":"ai/ai-agent.md","lastUpdated":1788243740000}'),n={name:"ai/ai-agent.md"};function o(r,l,s,u,g,d){return e(),a("div",null,l[0]||(l[0]=[t('<h1 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h1><blockquote><p>任何通过传感器（sensor）感知环境（environment）并通过执行器（actuator）作用于该环境的事物都可以被视为智能体（agent）</p></blockquote><p>比如：</p><ul><li>智能驾驶：根据道路情况，决定加速或刹车</li><li>扫地机器人：根据地面情节状况，决定清扫或离开</li><li>智能家居：根据屋内温度湿度，决定是否开启空调</li><li>游戏中的人机：根据玩家游戏动作，做出针对性动作</li><li>AI英语教练：根据学生发音，用词，提出改进意见</li></ul><h2 id="agent-应用开发" tabindex="-1">Agent 应用开发 <a class="header-anchor" href="#agent-应用开发" aria-label="Permalink to &quot;Agent 应用开发&quot;">​</a></h2><p>Agent类型</p><ul><li>按照场景 <ul><li>Action: 执行具体动作/任务的 Agent</li><li>Simulation: 模拟环境或行为的 Agent</li><li>Autonomous: 自主决策、独立运行的 Agent</li></ul></li><li>按照技术 <ul><li>Chatbot: 对话型智能体</li><li>Multi-Agent: 多智能体协作</li><li>RAG: 检索增强生成，结合外部知识库</li><li>Planning: 具备任务规划能力</li><li>Reflection: 具备自我反思能力</li><li>Evaluation: 具备评估/评判能力</li></ul></li><li>按照智能 <ul><li>Simple Reflex: 简单反射智能体</li><li>Model-basedReflex: 基于模型的反射智能体</li><li>Goal-based: 基于目标的智能体</li><li>Utility-based: 基于效用的智能体</li><li>Learning: 学习型智能体</li></ul></li></ul><p>核心能力</p><ul><li>Planning（规划）</li><li>Memory（记忆）</li><li>Tools（工具）</li><li>Action（执行）</li></ul><p>开发框架</p><ul><li>LangChain</li><li>LlamaIndex</li><li>Semantic Kernel</li></ul><h3 id="ai-agent分类详细说明" tabindex="-1">AI Agent分类详细说明 <a class="header-anchor" href="#ai-agent分类详细说明" aria-label="Permalink to &quot;AI Agent分类详细说明&quot;">​</a></h3><h4 id="基于智能水平、决策过程分类" tabindex="-1">基于智能水平、决策过程分类 <a class="header-anchor" href="#基于智能水平、决策过程分类" aria-label="Permalink to &quot;基于智能水平、决策过程分类&quot;">​</a></h4><ul><li><strong>简单反射智能体</strong>：这些智能体仅根据当前环境状态采取行动，并通过一组预定义的规则做出决策</li><li><strong>基于模型的反射智能体</strong>：与简单的反射智能体不同，这些智能体维护着一个内部世界模型，使他们能够考虑过去的行为并预测未来的状态。</li><li><strong>基于目标的智能体</strong>：这些智能体在工作时会考虑特定目标，并做出决策来使其更接近视线这些目标。</li><li><strong>基于效用的智能体</strong>：这些智能体会考虑他们所采取的行动的长期影响，而不是仅仅考虑短期利益，仅追求&quot;做到&quot;，还追求&quot;做好&quot;</li><li><strong>学习型智能体</strong>：这些智能体会不断学习，以便更好地适应他们的环境。</li></ul>',14)]))}const p=i(n,[["render",o]]);export{h as __pageData,p as default};
